#!/usr/bin/env bash
# Closes the remaining gap from the previous fix: agent.log now correctly
# shows registration succeeding ("Registered successfully as instance...")
# and the "No kiosk_start_command configured yet" line - then NOTHING else,
# ever, even though the very next line of code should have logged "Agent
# running as instance ... Press Ctrl+C to stop." within milliseconds.
#
# The previous fix (attaching a real FileHandler) only covers logging.*
# calls. An UNCAUGHT exception in a thread is reported through a
# completely SEPARATE mechanism - threading.excepthook - whose own
# default implementation ALSO just writes to sys.stderr, bypassing
# logging entirely. Since agent.main.run() itself executes on the Windows
# service wrapper's own background thread (see
# service_files/windows/opslab_agent_service.py), an exception anywhere
# in run()'s body - including right where the "Agent running..." log line
# never appeared - would vanish with zero trace under the real service:
# no crash reported to the SCM (matching sc.exe query showing RUNNING the
# whole time), no Event Log entry, nothing in agent.log, the service just
# silently doing nothing forever after.
#
# agent/main.py's setup_logging() now installs a custom
# threading.excepthook that routes uncaught thread exceptions through our
# own logging (which has a real file handler) instead of the default
# stderr-only hook.
#
# Verified: forced sys.stderr to None, raised a real uncaught exception in
# a thread, confirmed the full traceback (exception type, message, and
# call stack) lands in agent.log correctly.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "threading.excepthook" "$TMP_EXTRACT/agent/main.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. On Ewan, re-enroll once more (same as every earlier agent-side fix):"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "Then leave it running as the service and check the log again - this time"
echo "whatever was silently failing right after registration should actually show"
echo "up, with a real traceback:"
echo "    Get-Content \"C:\\ProgramData\\OpsLabAgent\\logs\\agent.log\" -Tail 50"
